def crear_envases_de_insumos_existentes(apps, schema_editor):
    """Los insumos que ya tienen stock lo reparten en envases llenos y uno en uso (si sobra algo),
    con el contenido y el precio de referencia que tenían. Así el stock no cambia."""
    Insumo = apps.get_model('core', 'Insumo')
    EnvaseInsumo = apps.get_model('core', 'EnvaseInsumo')
    for insumo in Insumo.objects.filter(total_kg__gt=0, kilos_por_saco__gt=0):
        if EnvaseInsumo.objects.filter(insumo=insumo).exists():
            continue
        contenido = Decimal(insumo.kilos_por_saco)
        llenos, resto = divmod(Decimal(insumo.total_kg), contenido)
        restantes = [contenido] * int(llenos) + ([resto] if resto else [])
        EnvaseInsumo.objects.bulk_create([
            EnvaseInsumo(insumo=insumo, tipo='envase', contenido=contenido, restante=restante,
                         precio=insumo.precio_saco or 0)
            for restante in restantes
        ])


